        case VectorElemKind::FP8:
            return elemType.isInteger(8);
        case VectorElemKind::F16:
            return elemType.isF16();
        case VectorElemKind::F32:
            return elemType.isF32();
        case VectorElemKind::BF16:
            return elemType.isBF16();
